; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"Var","generator":"egglog-demo-preview/v1","variants":{"Var":{"fields":["value"],"typst":"{value}","precedence":100}}}
(constructor Var (Ident) Expr)
