; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"Let","generator":"egglog-demo-preview/v1","variants":{"Let":{"fields":["arg0","arg1","arg2"],"typst":"upright(\"Let\")({arg0}, {arg1}, {arg2})","precedence":90}}}
(constructor Let (Ident Expr Expr) Expr)
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"Num","generator":"egglog-demo-preview/v1","variants":{"Num":{"fields":["value"],"typst":"{value}","precedence":100}}}
