; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"TVar","generator":"egglog-demo-preview/v1","variants":{"TVar":{"fields":["arg0"],"typst":"upright(\"TVar\")({arg0})","precedence":90}}}
