; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"TArr","generator":"egglog-demo-preview/v1","variants":{"TArr":{"fields":["arg0","arg1"],"typst":"upright(\"TArr\")({arg0}, {arg1})","precedence":90}}}
(constructor TArr (Type Type) Type :cost 1)
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"TInt","generator":"egglog-demo-preview/v1","variants":{"TInt":{"fields":[],"typst":"upright(\"TInt\")","precedence":90}}}
