; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"Forall","generator":"egglog-demo-preview/v1","variants":{"Forall":{"fields":["arg0","arg1"],"typst":"upright(\"Forall\")({arg0}, {arg1})","precedence":90}}}
