(constructor Cons (Ident Scheme Ctx) Ctx)

; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"ftvCtx","generator":"egglog-demo-preview/v1","variants":{"ftvCtx":{"fields":["arg0","arg1"],"typst":"upright(\"ftvCtx\")({arg0}, {arg1})","precedence":90}}}
