; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"ftv","generator":"egglog-demo-preview/v1","variants":{"ftv":{"fields":["arg0","arg1"],"typst":"upright(\"ftv\")({arg0}, {arg1})","precedence":90}}}
