; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"ftvScheme","generator":"egglog-demo-preview/v1","variants":{"ftvScheme":{"fields":["arg0","arg1"],"typst":"upright(\"ftvScheme\")({arg0}, {arg1})","precedence":90}}}
