; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"has-qs","generator":"egglog-demo-preview/v1","variants":{"has_qs":{"fields":["arg0","arg1","arg2"],"typst":"upright(\"has-qs\")({arg0}, {arg1}, {arg2})","precedence":90}}}
(relation has-qs (Ctx Type QuantifiedVs))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"has-qs-demand","generator":"egglog-demo-preview/v1","variants":{"has_qs_demand":{"fields":["arg0","arg1"],"typst":"upright(\"has-qs-demand\")({arg0}, {arg1})","precedence":90}}}
(relation has-qs-demand (Ctx Type))

;;;;;;;;;;;;;;;;;;;;;;
;; Expression size
;;;;;;;;;;;;;;;;;;;;;;
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"expr-size","generator":"egglog-demo-preview/v1","variants":{"expr_size":{"fields":["arg0","arg1"],"typst":"upright(\"expr-size\")({arg0}, {arg1})","precedence":90}}}
(relation expr-size (Expr i64))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-001","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","n":"n"},"positions":{"body/0/expr/1":"match_Num_0_1","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (Num n)))((expr-size e 1)))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-002","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","x":"x"},"positions":{"body/0/expr/1":"match_Var_0_1","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (Var x)))((expr-size e 1)))
;; asserted facts will be cleared so we define them as rules
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-003","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e"},"positions":{"body/0/expr/1":"match_True_0_1","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (True))) ((expr-size e 1)))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-004","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e"},"positions":{"body/0/expr/1":"match_False_0_1","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (False))) ((expr-size e 1)))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-005","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e"},"positions":{"body/0/expr/1":"match_MyUnit_0_1","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (MyUnit))) ((expr-size e 1)))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-006","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","e1":"e1","e2":"e2","s1":"s1","s2":"s2"},"positions":{"body/0/expr/1":"match_App_0_1","body/1/expr/0":"match_expr-size_1_0","body/2/expr/0":"match_expr-size_2_0","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (App e1 e2)) 
       (expr-size e1 s1) 
       (expr-size e2 s2))
      ((expr-size e (+ (+ s1 s2) 1))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-007","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","x":"x","e1":"e1","e2":"e2","s1":"s1","s2":"s2"},"positions":{"body/0/expr/1":"match_Let_0_1","body/1/expr/0":"match_expr-size_1_0","body/2/expr/0":"match_expr-size_2_0","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (Let x e1 e2)) 
       (expr-size e1 s1) 
       (expr-size e2 s2))
      ((expr-size e (+ (+ s1 s2) 1))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-008","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","x":"x","e1":"e1","s1":"s1"},"positions":{"body/0/expr/1":"match_Abs_0_1","body/1/expr/0":"match_expr-size_1_0","head/0/expr/0":"result_expr-size_0_0"}}}
(rule ((= e (Abs x e1)) 
       (expr-size e1 s1))
      ((expr-size e (+ s1 1))))

;;;;;;;;;;;;;;;;;;;;;;
;; Scheme and Context
;;;;;;;;;;;;;;;;;;;;;;

; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-009","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e"},"positions":{"body/0/expr/1":"match_TBool_0_1","head/0/expr/0":"result_ftv_0_0"}}}
(rule ((= e (TBool)))((ftv e (set-empty))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-010","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e"},"positions":{"body/0/expr/1":"match_TUnit_0_1","head/0/expr/0":"result_ftv_0_0"}}}
(rule ((= e (TUnit)))((ftv e (set-empty))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-011","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e"},"positions":{"body/0/expr/1":"match_TInt_0_1","head/0/expr/0":"result_ftv_0_0"}}}
(rule ((= e (TInt)))((ftv e (set-empty))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-012","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","x":"x"},"positions":{"body/0/expr/1":"match_TVar_0_1","head/0/expr/0":"result_ftv_0_0"}}}
(rule ((= e (TVar x)))((ftv e (set-insert (set-empty) x))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-013","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","fr":"fr","to":"to","s1":"s1","s2":"s2"},"positions":{"body/0/expr/1":"match_TArr_0_1","body/1/expr/0":"match_ftv_1_0","body/2/expr/0":"match_ftv_2_0","head/0/expr/0":"result_ftv_0_0"}}}
(rule ((= e (TArr fr to))
       (ftv fr s1)
       (ftv to s2))
      ((ftv e (set-union s1 s2))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-014","generator":"egglog-demo-preview/v1","labels":{"bindings":{"c":"c"},"positions":{"body/0/expr/1":"match_Nil_0_1","head/0/expr/0":"result_ftvCtx_0_0"}}}
(rule ((= c (Nil))) ((ftvCtx c (set-empty))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-015","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","qs":"qs","t":"t","fvs":"fvs"},"positions":{"body/0/expr/1":"match_Forall_0_1","body/1/expr/0":"match_ftv_1_0","head/0/expr/0":"result_ftvScheme_0_0"}}}
(rule ((= e (Forall qs t))
       (ftv t fvs))
      ((ftvScheme e (set-diff fvs qs)))) 
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-016","generator":"egglog-demo-preview/v1","labels":{"bindings":{"c":"c","x":"x","s":"s","n":"n","fvs1":"fvs1","fvs2":"fvs2"},"positions":{"body/0/expr/1":"match_Cons_0_1","body/1/expr/0":"match_ftvCtx_1_0","body/2/expr/0":"match_ftvScheme_2_0","head/0/expr/0":"result_ftvCtx_0_0"}}}
(rule ((= c (Cons x s n))
       (ftvCtx n fvs1)
       (ftvScheme s fvs2))
      ((ftvCtx c (set-union fvs1 fvs2))))


;; TODO: rewrite lookup to use native sets
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"lookup","generator":"egglog-demo-preview/v1","variants":{"lookup":{"fields":["arg0","arg1"],"typst":"upright(\"lookup\")({arg0}, {arg1})","precedence":90}}}
(constructor lookup (Ctx Ident) Scheme :cost 1000)
(rewrite (lookup (Cons x s tl) x) s)
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-018","generator":"egglog-demo-preview/v1","labels":{"bindings":{"t":"t","y":"y","s":"s","tl":"tl","x":"x"},"positions":{"body/0/expr/1":"match_lookup_0_1","head/0/expr/1":"result_lookup_0_1"}}}
(rule (
  (= t (lookup (Cons y s tl) x))
  (!= x y)
)(
  (union t (lookup tl x))
))

;;;;;;;;;;;;;;;;;;;;;;
;; Generalization and Instantiation
;;;;;;;;;;;;;;;;;;;;;;

; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"generalize","generator":"egglog-demo-preview/v1","variants":{"generalize":{"fields":["arg0","arg1"],"typst":"upright(\"generalize\")({arg0}, {arg1})","precedence":90}}}
(constructor generalize (Ctx Type) Scheme :cost 1000)
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"instantiate","generator":"egglog-demo-preview/v1","variants":{"instantiate":{"fields":["arg0","arg1"],"typst":"upright(\"instantiate\")({arg0}, {arg1})","precedence":90}}}
(constructor instantiate (Scheme i64) Type :cost 1000)

; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-019","generator":"egglog-demo-preview/v1","labels":{"bindings":{"ctx":"ctx"},"positions":{"body/0/expr/0":"match_has-qs-demand_0_0","head/0/expr/0":"result_has-qs_0_0"}}}
(rule ((has-qs-demand ctx (TInt)))
      ((has-qs ctx (TInt) (set-empty))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-020","generator":"egglog-demo-preview/v1","labels":{"bindings":{"ctx":"ctx"},"positions":{"body/0/expr/0":"match_has-qs-demand_0_0","head/0/expr/0":"result_has-qs_0_0"}}}
(rule ((has-qs-demand ctx (TBool)))
      ((has-qs ctx (TBool) (set-empty))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-021","generator":"egglog-demo-preview/v1","labels":{"bindings":{"ctx":"ctx"},"positions":{"body/0/expr/0":"match_has-qs-demand_0_0","head/0/expr/0":"result_has-qs_0_0"}}}
(rule ((has-qs-demand ctx (TUnit)))
      ((has-qs ctx (TUnit) (set-empty))))

; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-022","generator":"egglog-demo-preview/v1","labels":{"bindings":{"ctx":"ctx","fr":"fr","to":"to"},"positions":{"body/0/expr/0":"match_has-qs-demand_0_0","head/0/expr/0":"result_has-qs-demand_0_0","head/1/expr/0":"result_has-qs-demand_1_0"}}}
(rule ((has-qs-demand ctx (TArr fr to)))
      ((has-qs-demand ctx fr)
       (has-qs-demand ctx to)))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-023","generator":"egglog-demo-preview/v1","labels":{"bindings":{"ctx":"ctx","fr":"fr","to":"to","qs1":"qs1","qs2":"qs2"},"positions":{"body/0/expr/0":"match_has-qs-demand_0_0","body/1/expr/0":"match_has-qs_1_0","body/2/expr/0":"match_has-qs_2_0","head/0/expr/0":"result_has-qs_0_0"}}}
(rule ((has-qs-demand ctx (TArr fr to))
       (has-qs ctx fr qs1)
       (has-qs ctx to qs2))
      ((has-qs ctx (TArr fr to) (set-union qs1 qs2))))

; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-024","generator":"egglog-demo-preview/v1","labels":{"bindings":{"ctx":"ctx","x":"x","key-set":"key-set"},"positions":{"body/0/expr/0":"match_has-qs-demand_0_0","body/1/expr/0":"match_ftvCtx_1_0","head/0/expr/0":"result_has-qs_0_0"}}}
(rule ((has-qs-demand ctx (TVar x))
       (ftvCtx ctx key-set)
       (set-contains key-set x))
      ((has-qs ctx (TVar x) (set-empty))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-025","generator":"egglog-demo-preview/v1","labels":{"bindings":{"ctx":"ctx","x":"x","key-set":"key-set"},"positions":{"body/0/expr/0":"match_has-qs-demand_0_0","body/1/expr/0":"match_ftvCtx_1_0","head/0/expr/0":"result_has-qs_0_0"}}}
(rule ((has-qs-demand ctx (TVar x))
       (ftvCtx ctx key-set)
       (set-not-contains key-set x))
      ((has-qs ctx (TVar x) (set-insert (set-empty) x))))

; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-026","generator":"egglog-demo-preview/v1","labels":{"bindings":{"sc":"sc","ctx":"ctx","t":"t"},"positions":{"body/0/expr/1":"match_generalize_0_1","head/0/expr/0":"result_has-qs-demand_0_0"}}}
(rule ((= sc (generalize ctx t)))
      ((has-qs-demand ctx t)))
(rewrite (generalize ctx t)
         (Forall qs t)
         :when ((has-qs ctx t qs)))

; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"subst-fresh","generator":"egglog-demo-preview/v1","variants":{"subst_fresh":{"fields":["arg0","arg1","arg2"],"typst":"upright(\"subst-fresh\")({arg0}, {arg1}, {arg2})","precedence":90}}}
(constructor subst-fresh (QuantifiedVs Type i64) Type :cost 1000)
(rewrite (subst-fresh vs (TInt) c) (TInt))
(rewrite (subst-fresh vs (TBool) c) (TBool))
(rewrite (subst-fresh vs (TUnit) c) (TUnit))
(rewrite (subst-fresh vs (TArr fr to) c) 
         (TArr (subst-fresh vs fr c) (subst-fresh vs to c)))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-032","generator":"egglog-demo-preview/v1","labels":{"bindings":{"otype":"otype","vs":"vs","s":"s","c":"c"},"positions":{"body/0/expr/1":"match_subst-fresh_0_1","head/0/expr/1":"result_TVar_0_1"}}}
(rule ((= otype (subst-fresh vs (TVar s) c))
       (set-contains vs s))
      ((union otype (TVar (Fresh s c)))))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-033","generator":"egglog-demo-preview/v1","labels":{"bindings":{"otype":"otype","vs":"vs","s":"s","c":"c"},"positions":{"body/0/expr/1":"match_subst-fresh_0_1","head/0/expr/1":"result_TVar_0_1"}}}
(rule ((= otype (subst-fresh vs (TVar s) c))
       (set-not-contains vs s))
      ((union otype (TVar s))))

(rewrite (instantiate (Forall vs t) c)
         (subst-fresh vs t c))

;;;;;;;;;;;;;;;;;;;;;;
;; Injectivity
;;;;;;;;;;;;;;;;;;;;;;

; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-035","generator":"egglog-demo-preview/v1","labels":{"bindings":{"fr1":"fr1","to1":"to1","fr2":"fr2","to2":"to2"},"positions":{"body/0/expr/0":"match_TArr_0_0","body/0/expr/1":"match_TArr_0_1"}}}
(rule ((= (TArr fr1 to1) (TArr fr2 to2)))
      ((union fr1 fr2) 
       (union to1 to2)))

;;;;;;;;;;;;;;;;;;;;;;
;; Type inference
;;;;;;;;;;;;;;;;;;;;;;

; ctx |- expr : type
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"typeof","generator":"egglog-demo-preview/v1","variants":{"typeof":{"fields":["arg0","arg1","arg2"],"typst":"upright(\"typeof\")({arg0}, {arg1}, {arg2})","precedence":90}}}
(constructor typeof (Ctx Expr i64) Type :cost 1000)

;; Basic types (TInt, TBool, TUnit)
(rewrite (typeof ctx (Num x) c) (TInt))
(rewrite (typeof ctx (True) c) (TBool))
(rewrite (typeof ctx (False) c) (TBool))
(rewrite (typeof ctx (MyUnit) c) (TUnit))

; sc = lookup(ctx, x)
; t = instantiate(sc)
; ---------------
; ctx |- x : t
(rewrite (typeof ctx (Var x)  c)
         (instantiate (lookup ctx x) c))

(rewrite 
  (typeof ctx (Abs x e) c)
  (TArr (TVar (Fresh x c)) 
        (typeof (Cons x (Forall (set-empty) (TVar (Fresh x c)))
                      ctx)
                e cc))
    :when ((= cc (+ c 1))))

; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"typeinfer/rule-042","generator":"egglog-demo-preview/v1","labels":{"bindings":{"to":"to","ctx":"ctx","e1":"e1","e2":"e2","c":"c","c1":"c1","sz":"sz","c2":"c2"},"positions":{"body/0/expr/1":"match_typeof_0_1","body/2/expr/0":"match_expr-size_2_0","head/0/expr/0":"result_typeof_0_0","head/0/expr/1":"result_TArr_0_1"}}}
(rule ((= to (typeof ctx (App e1 e2) c))
       (= c1 (+ c 1))
       (expr-size e1 sz)
       (= c2 (+ c (+ sz 1))))
      ((union (typeof ctx e1 c1) 
              (TArr (typeof ctx e2 c2) to))))

(rewrite (typeof ctx (Let x e1 e2) c)
         (typeof (Cons x (generalize ctx (typeof ctx e1 c1)) 
                       ctx)
                 e2 c2)
    :when ((= c1 (+ c 1))
           (expr-size e1 sz)
           (= c2 (+ c (+ sz 1)))))

