; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"occurs-check","generator":"egglog-demo-preview/v1","variants":{"occurs_check":{"fields":["arg0","arg1"],"typst":"upright(\"occurs-check\")({arg0}, {arg1})","precedence":90}}}
(relation occurs-check (Ident Type))
