(rule (
    (assign s t1 v c)
    (malloc c t2)
)(
    (union (expr-points-to v) (AllocVar v))
))

;; If `t v = e` and `e -> a`, then `v -> a`.
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-002","generator":"egglog-demo-preview/v1","labels":{"bindings":{"s":"s","t":"t","v":"v","e":"e","a":"a"},"positions":{"body/0/expr/0":"match_assign_0_0","body/1/expr/0":"match_expr-points-to_1_0","head/0/expr/0":"result_expr-points-to_0_0"}}}
(rule (
    (assign s t v e)
    (= (expr-points-to e) a)
)(
    (union (expr-points-to v) a)
))

;; If `*v = u`, `v -> a`, and `u -> b`, then `a -> b`.
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-003","generator":"egglog-demo-preview/v1","labels":{"bindings":{"s":"s","v":"v","u":"u","a":"a","b":"b"},"positions":{"body/0/expr/0":"match_store_0_0","body/1/expr/0":"match_expr-points-to_1_0","body/2/expr/0":"match_expr-points-to_2_0","head/0/expr/0":"result_ptr-points-to_0_0"}}}
(rule (
    (store s v u)
    (= (expr-points-to v) a)
    (= (expr-points-to u) b)
)(
    (union (ptr-points-to a) b)
))

