; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-005","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","a":"a","ef":"ef","f":"f"},"positions":{"body/0/expr/0":"match_expr-points-to_0_0","body/1/expr/0":"match_field_1_0","head/0/expr/0":"result_expr-points-to_0_0"}}}
