))

;; If `u -> a` and `a -> b`, then `&(u->f) -> b`.
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-006","generator":"egglog-demo-preview/v1","labels":{"bindings":{"u":"u","a":"a","b":"b","e":"e","f":"f"},"positions":{"body/0/expr/0":"match_expr-points-to_0_0","body/1/expr/0":"match_ptr-points-to_1_0","body/2/expr/0":"match_addr_2_0","head/0/expr/0":"result_expr-points-to_0_0"}}}
(rule (
    (= (expr-points-to u) a)
    (= (ptr-points-to a) b)
    (addr e u f)
)(
    (union (expr-points-to e) b)
))

;; If `u -> a` and `&(u->f) -> b`, then `a -> b`.
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-007","generator":"egglog-demo-preview/v1","labels":{"bindings":{"u":"u","a":"a","e":"e","f":"f","b":"b"},"positions":{"body/0/expr/0":"match_expr-points-to_0_0","body/1/expr/0":"match_addr_1_0","body/2/expr/0":"match_expr-points-to_2_0","head/0/expr/0":"result_ptr-points-to_0_0"}}}
(rule (
    (= (expr-points-to u) a)
    (addr e u f)
    (= (expr-points-to e) b)
)(
    (union (ptr-points-to a) b)
))

;; If `(struct t){..., x, ...}` and `x -> b`, then `(struct t){..., x, ...} -> b`.
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-008","generator":"egglog-demo-preview/v1","labels":{"bindings":{"l":"l","f":"f","x":"x","b":"b"},"positions":{"body/0/expr/0":"match_struct-lit-field_0_0","body/1/expr/0":"match_expr-points-to_1_0","head/0/expr/0":"result_expr-points-to_0_0"}}}
(rule (
    (struct-lit-field l f x)
    (= (expr-points-to x) b)
)(
    (union (expr-points-to l) b)    
))

;; If `f(t* x)`, `f(v)`, and `v -> a`, then `x -> a`.
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-009","generator":"egglog-demo-preview/v1","labels":{"bindings":{"f":"f","x":"x","in":"in","out":"out","e":"e","v":"v","a":"a"},"positions":{"body/0/expr/0":"match_func_0_0","body/1/expr/0":"match_call_1_0","body/2/expr/0":"match_expr-points-to_2_0","head/0/expr/0":"result_expr-points-to_0_0"}}}
(rule (
    (func f x in out)
    (call e f v)
    (= (expr-points-to v) a)
)(
    (union (expr-points-to x) a)  
))

;; If `return u` in `f` and `u -> a`, then `f(z) -> a`.
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-010","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","f":"f","v":"v","s":"s","u":"u","a":"a"},"positions":{"body/0/expr/0":"match_call_0_0","body/1/expr/0":"match_func-stmt_1_0","body/2/expr/0":"match_return_2_0","body/3/expr/0":"match_expr-points-to_3_0","head/0/expr/0":"result_expr-points-to_0_0"}}}
(rule (
    (call e f v)
    (func-stmt f s)
    (return s u)
    (= (expr-points-to u) a)
)(
    (union (expr-points-to e) a)    
))

;; store rule
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"unification-points-to/rule-011","generator":"egglog-demo-preview/v1","labels":{"bindings":{"e":"e","u":"u","a":"a","b":"b"},"positions":{"body/0/expr/0":"match_load_0_0","body/1/expr/0":"match_expr-points-to_1_0","body/2/expr/0":"match_ptr-points-to_2_0","head/0/expr/0":"result_expr-points-to_0_0"}}}
(rule (
    (load e u)
    (= (expr-points-to u) a)
    (= (ptr-points-to a) b)
)(
    (union (expr-points-to e) b)
))

