(relation Bool (Val))
(Bool $True)
(Bool $False)

; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"merge-val","generator":"egglog-demo-preview/v1","variants":{"merge_val":{"fields":["arg0","arg1"],"typst":"upright(\"merge-val\")({arg0}, {arg1})","precedence":90}}}
