(rewrite (add-val $False x) $Top)
(rewrite (add-val x $True) $Top)
(rewrite (add-val x $False) $Top)
(rewrite (add-val (I x) (I y)) (I (+ x y)))

; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"eq-val","generator":"egglog-demo-preview/v1","variants":{"eq_val":{"fields":["arg0","arg1"],"typst":"upright(\"eq-val\")({arg0}, {arg1})","precedence":90}}}
