; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"VarT","generator":"egglog-demo-preview/v1","variants":{"V":{"fields":["arg0"],"typst":"upright(\"V\")({arg0})","precedence":90}}}
(datatype VarT (V String))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"Loc","generator":"egglog-demo-preview/v1","variants":{"L":{"fields":["arg0"],"typst":"upright(\"L\")({arg0})","precedence":90}}}
(datatype Loc (L i64))
; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"Exp","generator":"egglog-demo-preview/v1","variants":{"Add":{"fields":["left","right"],"typst":"{left} + {right}","precedence":50},"Eq":{"fields":["left","right"],"typst":"{left} = {right}","precedence":40},"Var":{"fields":["value"],"typst":"{value}","precedence":100},"Const":{"fields":["value"],"typst":"{value}","precedence":100}}}
