; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"ProgStmt","generator":"egglog-demo-preview/v1","variants":{"Ass":{"fields":["arg0","arg1"],"typst":"upright(\"Ass\")({arg0}, {arg1})","precedence":90},"If":{"fields":["arg0","arg1","arg2"],"typst":"upright(\"If\")({arg0}, {arg1}, {arg2})","precedence":90},"Goto":{"fields":["arg0"],"typst":"upright(\"Goto\")({arg0})","precedence":90},"Call":{"fields":["arg0"],"typst":"upright(\"Call\")({arg0})","precedence":90}}}
(datatype ProgStmt
    (Ass VarT Exp)
    (If VarT Loc Loc)
