; @egg-viz-json {"schema":"egg-viz/v1","kind":"dsl_type","id":"EndConst","generator":"egglog-demo-preview/v1","variants":{"EndConst":{"fields":[],"typst":"upright(\"EndConst\")","precedence":90}}}
