;; PROPAGATION

; propagate x = k
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"rw-analysis/rule-025","generator":"egglog-demo-preview/v1","labels":{"bindings":{"li":"li","x":"x","k":"k"},"positions":{"body/0/expr/0":"match_RProg_0_0"}}}
(rule (
    (RProg (L li) (Ass x (Const k)))
)(
    (set (const-prop (L (+ li 1)) x) k)
))

; propagate x = a + b (non-constant)
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"rw-analysis/rule-026","generator":"egglog-demo-preview/v1","labels":{"bindings":{"l":"l","x":"x","x1":"x1","x2":"x2","v1":"v1","v2":"v2","li":"li"},"positions":{"body/0/expr/0":"match_RProg_0_0","body/1/expr/1":"match_const-prop_1_1","body/2/expr/1":"match_const-prop_2_1","body/3/expr/1":"match_L_3_1"}}}
(rule (
    (RProg l (Ass x (Add x1 x2)))
    (= v1 (const-prop l x1))
    (= v2 (const-prop l x2))
    (= l (L li))
)(
    (set (const-prop (L (+ li 1)) x) (add-val v1 v2))
))

; propagate x = a == b
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"rw-analysis/rule-027","generator":"egglog-demo-preview/v1","labels":{"bindings":{"l":"l","x":"x","x1":"x1","x2":"x2","v1":"v1","v2":"v2","li":"li"},"positions":{"body/0/expr/0":"match_RProg_0_0","body/1/expr/1":"match_const-prop_1_1","body/2/expr/1":"match_const-prop_2_1","body/3/expr/1":"match_L_3_1"}}}
(rule (
    (RProg l (Ass x (Eq x1 x2)))
    (= v1 (const-prop l x1))
    (= v2 (const-prop l x2))
    (= l (L li))
)(
    (set (const-prop (L (+ li 1)) x) (eq-val v1 v2))
))

; propagate other vars
; @egg-viz-json {"schema":"egg-viz/v1","kind":"original_rule","id":"rw-analysis/rule-028","generator":"egglog-demo-preview/v1","labels":{"bindings":{"li":"li","x":"x","e":"e","val":"val","y":"y"},"positions":{"body/0/expr/0":"match_RProg_0_0","body/1/expr/1":"match_const-prop_1_1"}}}
(rule (
    (RProg (L li) (Ass (V x) e))
    (= val (const-prop (L li) (V y)))
